int phi (int n) {
    int result = n;
    for (int i=2; i*i<=n; ++i)
        if (n % i == 0) {
            while (n % i == 0) n /= i;
            result -= result / i;
        }
    if (n > 1) result -= result / n;
    return result;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int x = int(fragCoord.x / 1.0);
    int y = int(fragCoord.y / 1.0);

    if (phi(x) == y){
        fragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }
    fragColor = vec4(1.0, 1.0, 1.0, 1.0);
}
